import{c as o,Q as t,j as d,m as n}from"./chunks/framework.nsfXwikA.js";const m=JSON.parse('{"title":"Infrix DID context v1","description":"The JSON-LD context that every did:infrix document names. Immutable.","frontmatter":{"title":"Infrix DID context v1","description":"The JSON-LD context that every did:infrix document names. Immutable."},"headers":[],"relativePath":"ns/did/v1.md","filePath":"ns/did/v1.md"}'),a={name:"ns/did/v1.md"};function c(i,e,r,s,l,f){return t(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="infrix-did-context-version-1" tabindex="-1">Infrix DID context, version 1 <a class="header-anchor" href="#infrix-did-context-version-1" aria-label="Permalink to &quot;Infrix DID context, version 1&quot;">​</a></h1><p>This is the JSON-LD context named by every <code>did:infrix</code> DID document, at <code>https://infrix.opendlt.org/ns/did/v1</code>. A client that asks for JSON-LD (an <code>Accept</code> header of <code>application/ld+json</code> or <code>application/json</code>) receives the context document itself; a browser receives this page.</p><p>The document is immutable. The version is in the URL: a change to any term is published as a new version at a new URL, never as an edit of this one. Infrix core pins the SHA-256 of these exact bytes and refuses a processor run against any other copy.</p><ul><li>Raw document: <a href="/ns/did/v1.jsonld">v1.jsonld</a></li><li>SHA-256: <code>aaad098874fa0984e29a84bca5a1e52048bd54936513585e74f425bd1f530247</code></li></ul><p>It defines the terms the DID documents emit beyond the W3C DID core vocabulary: <code>AccumulateKeyPage</code>, <code>AccumulateKeyPageProof</code>, <code>keyPageUrl</code>, <code>keyBookUrl</code>, <code>pageIndex</code>, <code>threshold</code>, <code>CredentialRegistry</code>, <code>LinkedData</code>, <code>InfrixContract</code>, <code>InfrixAPI</code> and <code>description</code>.</p>',5)])])}const p=o(a,[["render",c]]);export{m as __pageData,p as default};
